    '{content:""!important;position:absolute!important;inset:0!important;z-index:2147483647!important;cursor:not-allowed!important;background:transparent!important;}';
  (document.head || document.documentElement).appendChild(s);
}
function _zccLock() {
  _zccInjectLockCss();
  document.documentElement.setAttribute('data-zcc-locked', '1');
}
function _zccUnlock() {
  document.documentElement.removeAttribute('data-zcc-locked');
}
// Lock immediately — but skip if the customer already validated this shop's
// ZIP in this session (avoids flash-of-disabled-buttons on page refresh).
var _priorValid = false;
try {
  _priorValid = sessionStorage.getItem('zcc:valid') === 'true' &&
                sessionStorage.getItem('zcc:shop') === SHOP;
} catch(e) {}
if (!_priorValid) {
