// Always fetch fresh config from the API so color/setting changes made in the
// admin are reflected on the storefront immediately. The metafield-embedded
// data-config attribute is intentionally ignored here: it is baked into
// Shopify's CDN-cached HTML at render time and can be stale for many minutes
// after a merchant saves new settings. The API endpoint returns
// Cache-Control: no-store so it is always up to date.
fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
  .then(function (r) {
    if (!r.ok) throw new Error("Widget config API returned " + r.status);
    return r.json();
  })
  .then(function (cfg) { renderWidget(cfg); })
  .catch(function (err) {
    console.warn("[Pinzo] Could not load widget config, using defaults:", err.message || err);
    renderWidget({});
  });

function renderWidget(cfg) {
  // Merge with defaults
  var D = {
    position: "inline",
    heading: "Check Delivery Availability",
    placeholder: "Enter your zip code",
    buttonText: "Check",
    successMessage: "Great news! We deliver to your area.",
    errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
    notFoundMessage: "We currently do not ship to this ZIP code.",
    primaryColor: "#008060",
    successColor: "#008060",
    errorColor: "#D72C0D",
    backgroundColor: "#FFFFFF",
    textColor: "#202223",
    borderRadius: "8",
    showEta: true,
    showZone: false,
    showWaitlistOnFailure: false,
    showCod: true,
    showReturnPolicy: true,
    showCutoffTime: true,
    showDeliveryDays: true,
    showDeliveryDate: true,
    showCountdown: true,
    showDeliveryFee: true,
    customCss: "",
    blockCartOnInvalid: false,
    showSocialProof: true,
  };
  // Default lockButtonsUntilZipCheck to true
  if (cfg.lockButtonsUntilZipCheck === undefined || cfg.lockButtonsUntilZipCheck === null) {
    cfg.lockButtonsUntilZipCheck = true;
  }
  Object.keys(D).forEach(function (k) {
    if (cfg[k] === undefined || cfg[k] === null) cfg[k] = D[k];
  });

  // Release pre-lock if feature is disabled OR widget is inline
  // (inline widget is directly visible — customer doesn't need to hunt for it)
  if (!cfg.lockButtonsUntilZipCheck || cfg.position === 'inline') {
    _zccUnlock();
  }

  var rad = cfg.borderRadius + "px";
  var WID = "zcc-" + ROOT_ID;

  if (cfg.position === "floating") {
    renderFloating(cfg, WID, rad);
  } else if (cfg.position === "popup") {
    renderPopup(cfg, WID, rad);
  } else {
    renderInline(cfg, WID, rad);
  }

  // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
  // until the customer validates their ZIP code
  if (cfg.blockCartOnInvalid) {
    blockCartButtonsInitial();
  }

  // If lockButtonsUntilZipCheck is enabled AND the widget is in floating or popup mode,
  // disable ATC/Buy Now buttons until the customer successfully validates their ZIP code.
  // This is separate from blockCartOnInvalid (which also re-blocks on invalid).
  // lockButtonsUntilZipCheck only activates in non-inline modes (floating/popup) because
  // in those modes the widget is not directly visible on the product page by default.
  if (cfg.lockButtonsUntilZipCheck && (cfg.position === "floating" || cfg.position === "popup")) {
    lockAtcButtonsForZipCheck();
  }
}

