          result += '}';
        }
        i = j; continue;
      }
    }
    // Regular rule: grab selector, prefix with #wid
    var sel = ""; var body = "";
    while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
    if (i < css.length) { i++; } // skip {
    var depth = 1;
    while (i < css.length && depth > 0) {
      if (css[i] === '{') depth++;
      if (css[i] === '}') depth--;
      if (depth > 0) body += css[i];
      i++;
    }
    if (sel.trim()) {
      // Split multiple selectors by comma and prefix each
      var selectors = sel.split(',').map(function(s) {
        s = s.trim();
        if (!s) return '';
        return '#' + wid + ' ' + s;
      }).filter(Boolean).join(', ');
      result += selectors + ' {' + body + '}';
    }
  }
  return result;
}

// ── Delivery date formatter ───────────────────────────────────────────────────
function formatDeliveryDate(isoDate) {
  if (!isoDate) return null;
  try {
    var parts = isoDate.split('-');
    var d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
    var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate();
  } catch(e) { return null; }
}

// ── Countdown timer functions ─────────────────────────────────────────────────
function getCountdownData(cutoffTime) {
  if (!cutoffTime) return null;
  var parts = cutoffTime.split(':');
  var cutoffHr = parseInt(parts[0], 10);
  var cutoffMin = parseInt(parts[1] || '0', 10);
  var now = new Date();
  var cutoff = new Date();
  cutoff.setHours(cutoffHr, cutoffMin, 0, 0);
  var diff = cutoff - now;
  if (diff <= 0) return { passed: true, hours: 0, minutes: 0 };
  var hours = Math.floor(diff / 3600000);
  var minutes = Math.floor((diff % 3600000) / 60000);
  return { passed: false, hours: hours, minutes: minutes };
}

function buildCountdownHtml(cutoffTime, widgetId) {
  var cd = getCountdownData(cutoffTime);
  if (!cd) return '';
  var colorClass, text;
  if (cd.passed) {
    colorClass = 'zcc-countdown--passed';
    text = 'Order now for next business day dispatch';
  } else {
    var totalMinutes = cd.hours * 60 + cd.minutes;
    if (totalMinutes > 180) colorClass = 'zcc-countdown--green';
    else if (totalMinutes > 60) colorClass = 'zcc-countdown--amber';
    else colorClass = 'zcc-countdown--red';
    text = 'Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch';
  }
  return '<div class="zcc-countdown ' + colorClass + '" id="' + widgetId + '-countdown">' + ICONS.clock + '<span>' + text + '</span></div>';
}

function startCountdownUpdater(widgetId, cutoffTime) {
  if (!cutoffTime) return;
  setInterval(function() {
    var el = document.getElementById(widgetId + '-countdown');
    if (!el) return;
    var cd = getCountdownData(cutoffTime);
    if (!cd) return;
    if (cd.passed) {
      el.className = 'zcc-countdown zcc-countdown--passed';
      el.innerHTML = ICONS.clock + '<span>Order now for next business day dispatch</span>';
      return;
    }
    var totalMinutes = cd.hours * 60 + cd.minutes;
    var cls = totalMinutes > 180 ? 'zcc-countdown--green' : totalMinutes > 60 ? 'zcc-countdown--amber' : 'zcc-countdown--red';
    el.className = 'zcc-countdown ' + cls;
    el.innerHTML = ICONS.clock + '<span>Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch</span>';
  }, 30000);
}

