    '<div class="zcc-result-icon">' + ICONS.xCircle + '</div>' +
    '<div class="zcc-result-content">' +
    '<div class="zcc-result-message">' + esc(data.message) + '</div>' +
    '</div></div>';
  if (cfg.showWaitlistOnFailure) {
    html +=
      '<div class="zcc-wl">' +
      '<div id="' + wid + '-wl-form">' +
      '<div class="zcc-wl-title">' + ICONS.mail + ' Get notified when we deliver to your area</div>' +
      '<input class="zcc-wl-input" type="text" id="' + wid + '-wl-name" placeholder="Your name (optional)" aria-label="Your name" />' +
      '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Your email address" aria-label="Your email address" required />' +
      '<input class="zcc-wl-input" type="text" id="' + wid + '-wl-zip" placeholder="ZIP code" aria-label="ZIP code" value="' + escAttr(zip) + '" required />' +
      '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button"><span class="zcc-wl-btn-icon">' + ICONS.mail + '</span><span class="zcc-wl-btn-label">Notify Me</span></button>' +
      '</div>' +
      '</div>';
  }
  res.innerHTML = html;

  if (cfg.showWaitlistOnFailure) {
    // Social proof count
    if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
      var wlSection = document.getElementById(wid + "-wl-name");
      if (wlSection && wlSection.parentNode) {
        var spEl = document.createElement('div');
        spEl.className = 'zcc-social-proof';
        var count = data.waitlistCount;
        var spIcon = document.createElement('span');
        spIcon.className = 'zcc-social-proof-icon';
        spIcon.innerHTML = ICONS.users;
        var spText = document.createTextNode(' Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area');
        spEl.appendChild(spIcon);
        spEl.appendChild(spText);
        wlSection.parentNode.insertBefore(spEl, wlSection);
      }
    }

    var wBtn = document.getElementById(wid + "-wl-btn");
    if (wBtn) {
      wBtn.addEventListener("click", function () {
        var nameEl = document.getElementById(wid + "-wl-name");
        var emailEl = document.getElementById(wid + "-wl-email");
        var zipEl = document.getElementById(wid + "-wl-zip");
        var name = nameEl ? nameEl.value.trim() : "";
        var email = emailEl ? emailEl.value.trim() : "";
        var wlZip = zipEl ? normalizeZip(zipEl.value) : zip;
        if (!email) { if (emailEl) emailEl.focus(); return; }
        if (!wlZip) { if (zipEl) zipEl.focus(); return; }
        joinWaitlist(wlZip, email, name, wBtn);
      });
    }
  }
}

